package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown by {@code CheckDailyOwnerLimit} when {@value #DAILY_LIMIT} or more owners have already
 * been created today (compared by {@code registrationDate} against the server's current date).
 * Handled by {@link DailyOwnerLimitExceptionHandler}, which responds 429 (Too Many Requests).
 */
public class DailyOwnerLimitException extends Exception {

    /** Maximum owners permitted to be created in a single day. */
    public static final int DAILY_LIMIT = 100;

    public DailyOwnerLimitException(int limit) {
        super("The daily limit of " + limit
                + " new owners has already been reached; try again tomorrow.");
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the {@code membershipNumber} to the freshly built {@link Owner} before it is saved.
 *
 * <p>The number is formatted {@code '<customerCode>-M<YY>'}, where {@code customerCode} is the
 * code assigned by {@link AssignCustomerCode} and YY is the last two digits of the owner's
 * {@code registrationDate} year (defaulted by {@link BuildOwner} when the request omits it),
 * e.g. {@code 'SPR-SMI-0007-M26'}. This step therefore runs after both are set.
 */
public class AssignMembershipNumber {

    public void service(@Val Owner owner) {
        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
    }
}

